INSERT INTO seed_question VALUES
  (1, 'ubot.demo.005@example.test', '해외에서 지도를 자주 써야 해서 로밍 요금이 많이 나오는 일을 피하는 방법 궁금합니다.', '해외에서 지도를 자주 써야 해서 로밍 요금이 많이 나오는 일을 피하는 방법 궁금합니다.', '해외에서 지도를 자주 써야 해서 로밍 요금이 많이 나오는 일을 피하는 방법 궁금합니다.', 1, '해외에서 지도를 자주 써야 해서 로밍 요금이 많이 나오는 일을 피하는 방법 궁금합니다', '해외에서 지도를 자주 써야 해서 로밍 요금이 많이 나오는 일을 피하려면, 로밍 상품에 가입하거나 데이터 사용을 제한하거나 차단 서비스를 이용하는 것이 좋습니다.', TRUE, NULL, 10),
  (2, 'ubot.demo.001@example.test', '출국 전날에 로밍 서비스를 신청하는 방법 알려주세요.', '출국 전날에 로밍 서비스를 신청하는 방법 알려주세요.', '출국 전날에 로밍 서비스를 신청하는 방법 알려주세요.', 1, '출국 전날에 로밍 서비스를 신청하는 방법 알려주세요', '출국 전날에 로밍 서비스를 신청하는 방법은 앱, 홈페이지, 고객센터 또는 로밍센터에서 신청할 수 있습니다.', TRUE, NULL, 38),
  (3, 'ubot.demo.011@example.test', '여행 중 영상 통화를 할 예정이라 로밍 요금이 많이 나오는 일을 피하는 방법 실천 방법을 알려주세요.', '여행 중 영상 통화를 할 예정이라 로밍 요금이 많이 나오는 일을 피하는 방법 실천 방법을 알려주세요.', '여행 중 영상 통화를 할 예정이라 로밍 요금이 많이 나오는 일을 피하는 방법 실천 방법을 알려주세요.', 1, '여행 중 영상 통화를 할 예정이라 로밍 요금이 많이 나오는 일을 피하는 방법 실천 방법을 알려주세요', '여행 중 영상 통화를 할 예정이라면 로밍 요금이 많이 나오는 일을 피하기 위해 로밍 상품에 가입하거나 데이터 사용을 제한하거나 차단 서비스를 이용하는 것이 좋습니다.', TRUE, NULL, 66),
  (4, 'ubot.demo.012@example.test', '해외 출장 일정을 확정한 뒤 로밍 서비스를 신청하는 방법 필요한 절차가 궁금합니다.', '해외 출장 일정을 확정한 뒤 로밍 서비스를 신청하는 방법 필요한 절차가 궁금합니다.', '해외 출장 일정을 확정한 뒤 로밍 서비스를 신청하는 방법 필요한 절차가 궁금합니다.', 1, '해외 출장 일정을 확정한 뒤 로밍 서비스를 신청하는 방법 필요한 절차가 궁금합니다', '해외 출장 일정을 확정한 뒤 로밍 서비스를 신청하려면, 앱, 홈페이지, 고객센터 또는 로밍센터에서 신청할 수 있습니다. 로밍 서비스는 출장 전에 신청하는 것이 원칙이며, 이미 해외에 도착한 경우에도 앱 또는 현지 와이파이로 통신사 앱에 접속하면 로밍 패스에 가입할 수 있습니다. 이용 기간은 앱의 로밍 메뉴에서 확인할 수 있습니다.', TRUE, NULL, 95),
  (5, 'ubot.demo.013@example.test', '태블릿으로 자료를 봐야 할 때 휴대폰 핫스팟을 켤 수 있는지 안내해 주세요.', '태블릿으로 자료를 봐야 할 때 휴대폰 핫스팟을 켤 수 있는지 안내해 주세요.', '태블릿으로 자료를 봐야 할 때 휴대폰 핫스팟을 켤 수 있는지 안내해 주세요.', 1, '태블릿으로 자료를 봐야 할 때 휴대폰 핫스팟을 켤 수 있는지 안내해 주세요', '태블릿으로 자료를 봐야 할 때 휴대폰 핫스팟을 켤 수 있습니다. 다만, 핫스팟을 사용하려면 테더링을 지원하는 단말기와 요금제를 이용해야 하며, 해당 조건이 충족되어야 합니다.', TRUE, NULL, 123),
  (6, 'ubot.demo.016@example.test', '출장지에서 노트북까지 연결할 것 같아 로밍 요금이 많이 나오는 일을 피하는 방법 어떤 대비가 좋을까요?', '출장지에서 노트북까지 연결할 것 같아 로밍 요금이 많이 나오는 일을 피하는 방법 어떤 대비가 좋을까요?', '출장지에서 노트북까지 연결할 것 같아 로밍 요금이 많이 나오는 일을 피하는 방법 어떤 대비가 좋을까요?', 1, '출장지에서 노트북까지 연결할 것 같아 로밍 요금이 많이 나오는 일을 피하는 방법 어떤 대비가 좋을까요', '출장지에서 노트북까지 연결할 것 같아 로밍 요금이 많이 나오는 일을 피하기 위해서는 로밍 상품에 가입하거나 데이터 사용을 제한하거나 차단 서비스를 이용하는 것이 좋습니다.', TRUE, NULL, 152),
  (7, 'ubot.demo.017@example.test', '여행 준비물을 챙기면서 로밍 서비스를 신청하는 방법 순서대로 안내해 주세요.', '여행 준비물을 챙기면서 로밍 서비스를 신청하는 방법 순서대로 안내해 주세요.', '여행 준비물을 챙기면서 로밍 서비스를 신청하는 방법 순서대로 안내해 주세요.', 1, '여행 준비물을 챙기면서 로밍 서비스를 신청하는 방법 순서대로 안내해 주세요', '로밍 서비스를 신청하기 위해서는 앱, 홈페이지, 고객센터 또는 로밍센터에서 신청할 수 있습니다. 여행 준비물을 챙기면서 로밍 서비스를 신청할 때는 이 중 하나를 선택하여 신청하는 것이 가능합니다.', TRUE, NULL, 180),
  (8, 'ubot.demo.014@example.test', '동남아 휴가를 준비하면서 데이터 로밍 비용이 어떻게 정해지는지 비교 기준을 알고 싶어요.', '동남아 휴가를 준비할 때 데이터 로밍 비용은 어떻게 정해지는지 비교 기준이 무엇인가요?', '동남아 휴가를 준비하면서 데이터 로밍 비용이 어떻게 정해지는지 비교 기준을 알고 싶어요.', 1, '동남아 휴가를 준비하면서 데이터 로밍 비용이 어떻게 정해지는지 비교 기준을 알고 싶어요', '동남아 휴가를 위한 데이터 로밍 비용은 방문 국가와 가입한 로밍 상품에 따라 달라지며, 해외 데이터 로밍 요금은 국가별로 다르게 정해집니다. 구체적인 비용은 상품 종류와 사용량에 따라 달라지므로, 해당 국가의 로밍 상품을 확인하여 비교해야 합니다.', TRUE, NULL, 209),
  (9, 'ubot.demo.005@example.test', '해외에서 지도를 자주 써야 해서 로밍 요금이 많이 나오는 일을 피하는 방법 궁금합니다.', '해외에서 지도를 자주 써야 해서 로밍 요금이 많이 나오는 일을 피하는 방법 궁금합니다.', '해외에서 지도를 자주 써야 해서 로밍 요금이 많이 나오는 일을 피하는 방법 궁금합니다.', 1, '해외에서 지도를 자주 써야 해서 로밍 요금이 많이 나오는 일을 피하는 방법 궁금합니다', '해외에서 지도를 자주 쓰는 경우 로밍 요금이 많이 나오는 것을 피하려면, 로밍 상품에 가입하거나 데이터 사용을 제한하거나 차단 서비스를 이용하는 것이 좋습니다.', FALSE, NULL, 237),
  (10, 'ubot.demo.006@example.test', '공항으로 가는 길에 로밍 서비스를 신청하는 방법 어디에서 할 수 있나요?', '공항으로 가는 길에 로밍 서비스를 신청하는 방법 어디에서 할 수 있나요?', '공항으로 가는 길에 로밍 서비스를 신청하는 방법 어디에서 할 수 있나요?', 1, '공항으로 가는 길에 로밍 서비스를 신청하는 방법 어디에서 할 수 있나요', '공항으로 가는 길에 로밍 서비스를 신청하는 방법은 앱, 홈페이지, 고객센터 또는 로밍센터에서 할 수 있습니다. 인천공항 제1·제2여객터미널의 로밍센터는 매일 06:00~22:00 운영하며, 해당 센터에서 로밍 패스 가입 상담과 로밍 설정 안내를 받을 수 있습니다. 그러나 근처 매장이 없습니다.', TRUE, NULL, 266),
  (11, 'ubot.demo.003@example.test', '다음 달 일본 여행을 앞두고 데이터 로밍 비용이 어떻게 정해지는지 설명해 주세요.', '데이터 로밍 비용은 어떻게 정해지는가?', NULL, 1, '다음 달 일본 여행을 앞두고 데이터 로밍 비용이 어떻게 정해지는지 설명해 주세요', '문의하신 내용은 현재 안내 자료로는 확인해 드리기 어렵습니다.', TRUE, NULL, 294),
  (12, 'ubot.demo.003@example.test', '다음 달 일본 여행을 앞두고 데이터 로밍 비용이 어떻게 정해지는지 설명해 주세요.', '일본 여행 시 데이터 로밍 비용의 계산 방식은 무엇인가?', NULL, 2, '다음 달 일본 여행을 앞두고 데이터 로밍 비용이 어떻게 정해지는지 설명해 주세요', '문의하신 내용은 현재 안내 자료로는 확인해 드리기 어렵습니다.', TRUE, NULL, 323),
  (13, 'ubot.demo.007@example.test', '출장으로 미국에 가게 되어 데이터 로밍 비용이 어떻게 정해지는지 미리 확인할 방법이 있나요?', '출장으로 미국에 가게 되어 데이터 로밍 비용이 어떻게 정해지는지 미리 확인할 방법이 있나요?', '출장으로 미국에 가게 되어 데이터 로밍 비용이 어떻게 정해지는지 미리 확인할 방법이 있나요?', 1, '출장으로 미국에 가게 되어 데이터 로밍 비용이 어떻게 정해지는지 미리 확인할 방법이 있나요', '미국에 출장 가시는 경우, 현재 가입한 Ubot 로밍 상품인 ''Ubot 로밍 대만 베이직''은 대만 지역에만 적용되며, 미국 지역에 대한 로밍 서비스는 포함되어 있지 않습니다. 따라서 미국에서의 데이터 로밍 비용은 해당 상품에 따라 정해지지 않으며, 해외 데이터 로밍 요금은 방문 국가와 가입한 로밍 상품에 따라 달라지므로, 미국 방문 시 추가로 로밍 상품을 가입하거나, 해당 국가에 맞는 로밍 요금제를 사전에 구매해야 합니다. 현재 이용 중인 회선의 로밍 상품은 대만 지역에 한해 적용되므로, 미국 출장 시 데이터 로밍 비용이 발생하지 않을 수 있습니다. 자세한 정보는 고객센터 또는 통신사 앱에서 확인하시기 바랍니다.', TRUE, NULL, 351),
  (14, 'ubot.demo.013@example.test', '태블릿으로 자료를 봐야 할 때 휴대폰 핫스팟을 켤 수 있는지 안내해 주세요.', '태블릿으로 자료를 봐야 할 때 휴대폰 핫스팟을 켤 수 있는지 안내해 주세요.', '태블릿으로 자료를 봐야 할 때 휴대폰 핫스팟을 켤 수 있는지 안내해 주세요.', 1, '태블릿으로 자료를 봐야 할 때 휴대폰 핫스팟을 켤 수 있는지 안내해 주세요', '문의하신 내용은 현재 안내 자료로는 확인해 드리기 어렵습니다.', FALSE, NULL, 380),
  (15, 'ubot.demo.011@example.test', '여행 중 영상 통화를 할 예정이라 로밍 요금이 많이 나오는 일을 피하는 방법 실천 방법을 알려주세요.', '여행 중 영상 통화를 할 예정이라 로밍 요금이 많이 나오는 일을 피하는 방법 실천 방법을 알려주세요.', '여행 중 영상 통화를 할 예정이라 로밍 요금이 많이 나오는 일을 피하는 방법 실천 방법을 알려주세요.', 1, '여행 중 영상 통화를 할 예정이라 로밍 요금이 많이 나오는 일을 피하는 방법 실천 방법을 알려주세요', '여행 중 영상 통화를 할 예정이라면 로밍 요금이 많이 나오는 일을 피하기 위해 로밍 상품에 가입하거나 데이터 사용을 제한하거나 차단 서비스를 이용하는 것이 좋습니다.', FALSE, NULL, 408),
  (16, 'ubot.demo.009@example.test', '유럽 여러 나라를 방문할 예정이라 데이터 로밍 비용이 어떻게 정해지는지 알려주시면 좋겠습니다.', '유럽 여러 나라를 방문할 예정이라 데이터 로밍 비용이 어떻게 정해지는지 알려주시면 좋겠습니다.', '유럽 여러 나라를 방문할 예정이라 데이터 로밍 비용이 어떻게 정해지는지 알려주시면 좋겠습니다.', 1, '유럽 여러 나라를 방문할 예정이라 데이터 로밍 비용이 어떻게 정해지는지 알려주시면 좋겠습니다', '유럽 여러 나라를 방문할 때 데이터 로밍 비용은 Ubot 로밍 상품이 적용되는 국가에 따라 달라지며, Ubot 로밍 상품은 유럽의 프랑스, 독일, 스페인, 이탈리아 등 16개국에서 이용할 수 있습니다. 그러나 현재 이용 중인 회선의 로밍 상품이 없으므로, 해당 국가에서의 로밍 요금은 적용되지 않습니다. 또한, 사용자 정보에 따르면 최근 청구서(2026년 9월 기준)에는 로밍 요금이 0원으로 기재되어 있어, 유럽 방문 시 로밍 비용이 발생하지 않을 가능성이 있습니다.', TRUE, NULL, 437),
  (17, 'ubot.demo.012@example.test', '해외 출장 일정을 확정한 뒤 로밍 서비스를 신청하는 방법 필요한 절차가 궁금합니다.', '해외 출장 일정을 확정한 뒤 로밍 서비스를 신청하는 방법 필요한 절차가 궁금합니다.', '해외 출장 일정을 확정한 뒤 로밍 서비스를 신청하는 방법 필요한 절차가 궁금합니다.', 1, '해외 출장 일정을 확정한 뒤 로밍 서비스를 신청하는 방법 필요한 절차가 궁금합니다', '해외 출장 일정을 확정한 뒤 로밍 서비스를 신청하려면, 앱, 홈페이지, 고객센터 또는 로밍센터에서 신청할 수 있습니다.', FALSE, NULL, 465),
  (18, 'ubot.demo.016@example.test', '출장지에서 노트북까지 연결할 것 같아 로밍 요금이 많이 나오는 일을 피하는 방법 어떤 대비가 좋을까요?', '출장지에서 노트북까지 연결할 것 같아 로밍 요금이 많이 나오는 일을 피하는 방법 어떤 대비가 좋을까요?', '출장지에서 노트북까지 연결할 것 같아 로밍 요금이 많이 나오는 일을 피하는 방법 어떤 대비가 좋을까요?', 1, '출장지에서 노트북까지 연결할 것 같아 로밍 요금이 많이 나오는 일을 피하는 방법 어떤 대비가 좋을까요', '출장지에서 노트북까지 연결할 것 같아 로밍 요금이 많이 나오는 일을 피하기 위해서는 로밍 상품에 가입하거나 데이터 사용을 제한하거나 차단 서비스를 이용하는 것이 좋습니다.', FALSE, NULL, 494),
  (19, 'ubot.demo.017@example.test', '여행 준비물을 챙기면서 로밍 서비스를 신청하는 방법 순서대로 안내해 주세요.', '여행 준비물을 챙기면서 로밍 서비스를 신청하는 방법 순서대로 안내해 주세요.', '여행 준비물을 챙기면서 로밍 서비스를 신청하는 방법 순서대로 안내해 주세요.', 1, '여행 준비물을 챙기면서 로밍 서비스를 신청하는 방법 순서대로 안내해 주세요', '로밍 서비스를 신청하는 방법은 앱, 홈페이지, 고객센터 또는 로밍센터에서 가능합니다. 여행 준비물을 챙기면서 로밍 서비스를 신청할 때는 이 중 하나를 선택하여 신청하시면 됩니다.', FALSE, NULL, 522),
  (20, 'ubot.demo.014@example.test', '동남아 휴가를 준비하면서 데이터 로밍 비용이 어떻게 정해지는지 비교 기준을 알고 싶어요.', '동남아 휴가를 준비할 때 데이터 로밍 비용은 어떻게 정해지는지 비교 기준이 무엇인가요?', '동남아 휴가를 준비하면서 데이터 로밍 비용이 어떻게 정해지는지 비교 기준을 알고 싶어요.', 1, '동남아 휴가를 준비하면서 데이터 로밍 비용이 어떻게 정해지는지 비교 기준을 알고 싶어요', '동남아 휴가를 위한 데이터 로밍 비용은 방문 국가와 가입한 로밍 상품에 따라 달라지며, 해외 데이터 로밍 요금은 국가별로 다르게 정해집니다. 구체적인 비용은 상품 종류와 사용량에 따라 달라지므로, 해당 국가의 로밍 상품을 확인하여 비교해야 합니다.', FALSE, NULL, 551),
  (21, 'ubot.demo.018@example.test', '해외 체류 일정이 잡혀 데이터 로밍 비용이 어떻게 정해지는지 예산을 잡으려 합니다.', '해외 체류 일정이 잡혀 있을 때 데이터 로밍 비용은 어떻게 예산되는지 알려주세요.', NULL, 1, '해외 체류 일정이 잡혀 데이터 로밍 비용이 어떻게 정해지는지 예산을 잡으려 합니다', '문의하신 내용은 현재 안내 자료로는 확인해 드리기 어렵습니다.', TRUE, NULL, 579),
  (22, 'ubot.demo.018@example.test', '해외 체류 일정이 잡혀 데이터 로밍 비용이 어떻게 정해지는지 예산을 잡으려 합니다.', '데이터 로밍 비용을 예산하기 위해 어떤 요소들이 고려되나요?', NULL, 2, '해외 체류 일정이 잡혀 데이터 로밍 비용이 어떻게 정해지는지 예산을 잡으려 합니다', '문의하신 내용은 현재 안내 자료로는 확인해 드리기 어렵습니다.', TRUE, NULL, 608),
  (23, 'ubot.demo.018@example.test', '해외 체류 일정이 잡혀 데이터 로밍 비용이 어떻게 정해지는지 예산을 잡으려 합니다.', '해외 체류 기간에 따라 데이터 로밍 비용이 어떻게 달라지나요?', NULL, 3, '해외 체류 일정이 잡혀 데이터 로밍 비용이 어떻게 정해지는지 예산을 잡으려 합니다', '문의하신 내용은 현재 안내 자료로는 확인해 드리기 어렵습니다.', TRUE, NULL, 636),
  (24, 'ubot.demo.019@example.test', '기본 용량을 끝까지 사용한 다음 인터넷이 완전히 끊기는지 어떤 일이 생기는지 궁금합니다.', '기본 용량을 끝까지 사용한 다음 인터넷이 완전히 끊기는지 어떤 일이 생기는지 궁금합니다.', '기본 용량을 끝까지 사용한 다음 인터넷이 완전히 끊기는지 어떤 일이 생기는지 궁금합니다.', 1, '기본 용량을 끝까지 사용한 다음 인터넷이 완전히 끊기는지 어떤 일이 생기는지 궁금합니다', 'Ubot 요금제는 107가지이며, 다음 종류가 있습니다.
