INSERT INTO question_log (user_id, user_question, sub_question, user_text, sub_question_index, normalized_question, llm_question, ranking_eligible, region, created_at) SELECT u.user_id, s.user_question, s.sub_question, s.user_text, s.sub_question_index, s.normalized_question, s.llm_question, s.ranking_eligible, CASE WHEN s.seed_key % 2 = 0 THEN 'GYEONGGI' ELSE 'SEOUL' END, a.at - interval '2 hours' + make_interval(secs => s.offset_seconds) FROM seed_question s JOIN users u ON u.email = s.email CROSS JOIN seed_anchor a;
INSERT INTO faq_log (question_log_id, faq_id, rank, similarity, created_at) SELECT i.question_log_id, f.faq_id, f.rank, f.similarity, i.created_at FROM seed_faq_log f JOIN inserted_question i ON i.seed_key = f.question_seed_key;
